## 1️⃣ `agenda.js` — núcleo de agendamento

```js
'use strict';

const S = require('node-schedule');               // evita colidir com a variável local `schedule`
const { loadData, saveData } = require('./data'); // seus utils de persistência
const moment = require('moment');

// ----------------------------- Configuração -----------------------------
const TIPOS = ['abrir', 'fechar'];
const INTERVALO_CHECAGEM = 60_000; // 1 minuto (ms)
const CAMINHO_DADOS = process.env.CAMINHO_DADOS || 'dados/agendas.json';

let AGENDADOS = loadData(CAMINHO_DADOS) || {}; // { groupId: { tipo, time, nextDate, processadaEm } }

// ----------------------------- Helpers -----------------------------

/** Aplica a ação concreta (mudar modo de anúncio, enviar aviso etc.) */
async function executarAcao(groupId, tipo) {
    switch (tipo) {
        case 'fechar': {
            await client.groupSettingUpdate(groupId, 'announcement');
            await promitirDelay(500);
            const aviso = await enviarAoGrupo(groupId, '*Grupo fechado com sucesso 🔒*');
            console.log(aviso ? `[agenda] ✅ Fechei o grupo ${groupId}`, '[agenda] ⚠️ Aviso não entregue`);
            break;
        }

        case 'abrir': {
            await client.groupSettingUpdate(groupId, 'not_announcement');
            await promitirDelay(500);
            const aviso = await enviarAoGrupo(groupId, '*Grupo aberto com sucesso 🔓*');
            console.log(aviso ? `[agenda] ✅ Abri o grupo ${groupId}` : '[agenda] ⚠️ Aviso não entregue`);
            break;
        }

        default:
            console.warn(`[agenda] Tipo de operação ignorado: "${tipo}".`);
    }
}

/** Faz uma chamada assíncrona com retry-lite e captura erros sem jogar o processo inteiro fora. */
async function enviarAoGrupo(groupId, texto) {
    try {
        return client.sendMessage(groupId, { text }); // ajuste pro seu client
    } catch (err) {
        console.warn(`[agenda] Não consegui enviar aviso ao grupo ${groupId}: ${err.message}`);
        return null;
    }
}

/** Delay convertido em Promise (não depende mais da função global `delay`). */
async function promitirDelay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Compara data + horário em uma única referência temporal.
 *  Aceita nextDate como "20/06/2025" OU "2025-06-20".
 *  Se a data não for reconhecida, cai para hoje.
 */
function referenciaTempo(opera) {
    const bruta = (opera.nextDate || '').trim();
    const candidatos = [
        moment(bruta, 'DD/MM/YYYY', true),
        moment(bruta, 'YYYY-MM-DD', true),
    ];
    const dataBase = candidatos.find(m => m.isValid()) || moment();
    const alvo = dataBase.clone()
        .set({ hour: +opera.time.slice(0, 2), minute: +opera.time.slice(3, 5), second: 0 });
    return alvo;
}

/** Diz se o horário HH:MM da operação já chegou (considerando a data do nextDate). */
function operaJáValeu(opera) {
    return referenciaTempo(opera).isBefore(moment());
}

// ----------------------------- Checagem principal -----------------------------

/** Chama o ciclo completo de verificação. É seguro rodar várias vezes */
async function checarOperacoes() {
    const agoraMs = Date.now();
    const entradas = Object.entries(AGENDADOS);

    for (const [groupId, operacoes] of entradas) {
        let mudou = false;

        for (const [tipo, op] of Object.entries(operacoes)) {
            // Valida o formato antes de mexer em nada
            if (typeof op.time !== 'string' || typeof op.nextDate !== 'string'
                    || !/^\d{2}:\d{2}$/.test(op.time)) {
                console.warn(`[agenda] Registro inconsistente do grupo ${groupId} — removendo.`);
                delete AGENDADOS[groupId];
                continue;
            }

            try {
                if (!operaJáValeu(op)) continue; // ainda não chegou a vez

                const proximo = calculateNextTime(op); // mantém a assinatura do seu util
                op.nextDate      = proximo.nextDate;
                op.timeRemaining = proximo.timeRemaining;
                op.processadaEm  = agoraMs;
                mudou = true;

                await executarAcao(groupId, tipo);
            } catch (err) {
                console.error(`[agenda] Falha ao processar grupo ${groupId}:`, err.message);
                delete AGENDADOS[groupId]; // tira do ar qualquer registro quebrado
            }
        }

        if (mudou) {
            saveData(CAMINHO_DADOS);
        }
    }
}

/** Roda uma checagem pontual (ex.: chamado via `/openall` do comando) */
async function checarManualmente() {
    try { await checarOperacoes(); } catch { /* ignora */ }
}

// ----------------------------- Lifecycle -----------------------------

async function iniciar() {
    AGENDADOS = loadData(CAMINHO_DADOS) || {};
    if (Object.keys(AGENDADOS).length) {
        console.info(`[agenda] 🗂️ Carregados ${Object.keys(AGENDADOS).length} grupos.`);
    }

    const tick = async () => { try { await checarOperacoes(); } catch { /* segue chutando */ } };
    setInterval(tick, INTERVALO_CHECAGEM);

    // Cancela jobs do node-schedule ao desligar
    const parar = () => {
        clearInterval(Date.now() / 1000 <= 0 ? Infinity : setInterval.tickHandle); // segurança
        clearInterval(setIntervalHandle);
        try {
            const jobs = S.getJobsByNamePattern('* * * * *');
            jobs.forEach(j => j.stop(true));
        } catch (_) { /* sem jobs registrados — tranquilo */ }
        process.exit(0);
    };
    process.once('SIGINT', parar);
    process.once('SIGTERM', parar);

    console.info('[agenda] 🤖 Em execução. Pressione Ctrl+C para sair.');
}

// Atalho rápido para testar sem esperar o tick
function dispararVerificacao() { checarManualmente(); }

iniciar().catch(err => { console.error('[agenda] Falha na inicialização:', err); process.exit(1); });


// ============================== Exportações úteis ========================
module.exports = { AGENDADOS, checarOperacoes, checarManualmente, dispararVerificacao };
```

💡 Se você continuar usando `setInterval(checkScheduledOperations, …)` direto no arquivo antigo, troque por:

